export const getGenerateInsightsUrl = (params?: GenerateInsightsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/ledger-api/ai/insights?${stringifiedParams}` : `/ledger-api/ai/insights`
}

/**
 * @summary Generate insights for current filters
 */
export const generateInsights = async (params?: GenerateInsightsParams, options?: Parameters<typeof customFetch>[1]): Promise<InsightsResponse> => {

  return customFetch<InsightsResponse>(getGenerateInsightsUrl(params),
  {
    ...options,
    method: 'POST'


  }
);}





